probe2 = """
{
  a: __type(name: "VariantDetailsSequencingTypeData") { fields { name } }
  b: __type(name: "VariantDetailsJointSequencingTypeData") { fields { name } }
}
"""
r = gql(probe2)
d = r.get("data", r)
print("SEQTYPE:", [f["name"] for f in d["a"]["fields"]])
print("JOINT  :", [f["name"] for f in d["b"]["fields"]])

q = """
{
  variant(variantId: "1-11796321-G-A", dataset: gnomad_r4) {
    variant_id
    rsids
    exome  { ac an af homozygote_count filters populations { id ac an homozygote_count } }
    genome { ac an af homozygote_count filters populations { id ac an homozygote_count } }
    joint  { ac an    homozygote_count filters populations { id ac an homozygote_count } }
  }
}
"""
r = gql(q)
if "errors" in r:
    print("ERRORS:", json.dumps(r["errors"])[:1500])
v = r.get("data", {}).get("variant")
print("variant_id:", v["variant_id"], "rsids:", v["rsids"])

for src in ["exome", "genome", "joint"]:
    blk = v.get(src)
    if not blk:
        print(f"\n{src}: None"); continue
    ac, an = blk["ac"], blk["an"]
    print(f"\n=== {src} ===  AC={ac}  AN={an}  AF={ac/an:.6f}  nhom={blk['homozygote_count']}  filters={blk['filters']}")
    # top-level ancestry groups only (exclude sex-stratified sub-entries containing '_')
    rows = [p for p in blk["populations"] if "_" not in p["id"] and p["an"] > 0]
    for p in sorted(rows, key=lambda x: -x["ac"]/x["an"]):
        print(f"   {p['id']:>6}  AC={p['ac']:>7}  AN={p['an']:>8}  AF={p['ac']/p['an']:.4f}")
